use guard_command::CommandModelRequestV1;
use guard_contracts::{
    ApprovalChallengeRequestV3, ApprovalChallengeRequestV4, ApprovalConsumeRequestV3,
    ApprovalConsumeRequestV4, ApprovalValidateRequestV3, ApprovalValidateRequestV4,
    GuardHookEnvelopeV2, NativeHookRequestV1, RuntimeCapabilitiesV1, GUARD_HOOK_ENVELOPE_V2_SCHEMA,
    MAX_NATIVE_RESPONSE_BYTES, NATIVE_APPROVAL_ERROR_CODES, NATIVE_APPROVAL_MAX_BYTES,
    NATIVE_PROTOCOL_VERSION, NATIVE_RESIDENT_LIFECYCLE_ERROR_CODES,
};
use guard_hook_core::review_post_tool;
use serde::Deserialize;
use serde_json::Value;

use crate::policy_store::PolicySnapshotStore;

#[derive(Debug, Deserialize)]
#[serde(tag = "operation", content = "request", rename_all = "snake_case")]
pub(crate) enum ResidentOperationV1 {
    CommandModel(CommandModelRequestV1),
    PreToolUse(CommandModelRequestV1),
    PolicySnapshotPush(Value),
    ApprovalChallenge(ApprovalChallengeRequestV3),
    ApprovalValidate(ApprovalValidateRequestV3),
    ApprovalConsume(ApprovalConsumeRequestV3),
    ApprovalChallengeV4(ApprovalChallengeRequestV4),
    ApprovalValidateV4(ApprovalValidateRequestV4),
    ApprovalConsumeV4(ApprovalConsumeRequestV4),
    Health(Value),
    Shutdown(Value),
}

#[derive(Debug, Deserialize)]
#[serde(untagged)]
pub(crate) enum ResidentRequestV1 {
    Operation(Box<ResidentOperationV1>),
    Edge(GuardHookEnvelopeV2),
    Hook(NativeHookRequestV1),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum LifecycleDisposition {
    Continue,
    Shutdown,
}

#[derive(Debug)]
pub(crate) struct ResidentEvaluation {
    pub(crate) response: Vec<u8>,
    pub(crate) disposition: LifecycleDisposition,
}

pub(crate) fn capabilities() -> RuntimeCapabilitiesV1 {
    let mut features = vec![
        "post-tool-inline-v1".into(),
        "post-tool-source-read-v1".into(),
        "oneshot-v1".into(),
        "framed-serve-v1".into(),
        "resident-protocol-v2".into(),
        "bounded-admission-v2".into(),
        "overload-signal-v1".into(),
        "panic-containment-v1".into(),
        "rule-contract-v2".into(),
        "pre-tool-command-model-shadow-v1".into(),
        "resident-command-model-shadow-v1".into(),
        "pre-tool-command-authority-v1".into(),
        "pre-tool-generic-authority-v1".into(),
        guard_contracts::NATIVE_COMMAND_PROGRAM_CAPABILITY.into(),
        guard_contracts::NATIVE_COMMAND_CONTROL_FENCE_CAPABILITY.into(),
        "policy-snapshot-v3".into(),
        "policy-snapshot-push-v1".into(),
        "policy-snapshot-resident-generation-v1".into(),
        "native-approval-artifact-v3".into(),
        "native-approval-challenge-v3".into(),
        "native-approval-validation-v3".into(),
        "native-approval-consume-v3".into(),
        "native-approval-webauthn-v4".into(),
        "native-approval-challenge-v4".into(),
        "native-approval-validation-v4".into(),
        "native-approval-consume-v4".into(),
        "native-approval-replay-memory-v1".into(),
        "native-policy-in-memory-v1".into(),
        "hook-envelope-v2".into(),
        "native-resident-client-v1".into(),
        "native-resident-lifecycle-v1".into(),
    ];
    if cfg!(windows) {
        features.push("authenticated-loopback-resident-v1".into());
        features.push("post-tool-source-read-windows-handles-v1".into());
    }
    if cfg!(unix) {
        features.push("authenticated-unix-resident-v1".into());
    }
    RuntimeCapabilitiesV1 {
        protocol_version: NATIVE_PROTOCOL_VERSION,
        runtime_version: crate::PACKAGE_VERSION.to_owned(),
        rule_digest: guard_rule_contract::rule_digest(),
        build_sha: crate::BUILD_SHA.to_owned(),
        target: format!("{}-{}", std::env::consts::ARCH, std::env::consts::OS),
        features,
    }
}

#[cfg(test)]
pub(crate) fn evaluate_resident_bytes(
    bytes: &[u8],
    policy_store: Option<&PolicySnapshotStore>,
) -> Result<ResidentEvaluation, String> {
    evaluate_resident_bytes_started(bytes, policy_store, std::time::Instant::now())
}

pub(crate) fn evaluate_resident_bytes_started(
    bytes: &[u8],
    policy_store: Option<&PolicySnapshotStore>,
    started_at: std::time::Instant,
) -> Result<ResidentEvaluation, String> {
    let value = strict_json_value(bytes)?;
    if bytes.len() > NATIVE_APPROVAL_MAX_BYTES
        && matches!(
            value.get("operation").and_then(Value::as_str),
            Some(
                "approval_challenge"
                    | "approval_validate"
                    | "approval_consume"
                    | "approval_challenge_v4"
                    | "approval_validate_v4"
                    | "approval_consume_v4",
            )
        )
    {
        return Err("native_approval_request_bounds_exceeded".to_owned());
    }
    if value.get("operation").and_then(Value::as_str) == Some("policy_snapshot_push") {
        let object = value
            .as_object()
            .ok_or_else(|| "native_policy_snapshot_push_invalid".to_owned())?;
        if object
            .keys()
            .any(|key| !matches!(key.as_str(), "operation" | "request" | "deadline_budget_ms"))
        {
            return Err("native_policy_snapshot_push_invalid".to_owned());
        }
    }
    if value.get("operation").is_none()
        && value.get("schema").and_then(Value::as_str) != Some(GUARD_HOOK_ENVELOPE_V2_SCHEMA)
    {
        crate::oneshot::validate_request_policy_snapshot(&value)?;
    }
    let request: ResidentRequestV1 = serde_json::from_value(value)
        .map_err(|_| "native_resident_request_invalid_json".to_owned())?;
    let mut disposition = LifecycleDisposition::Continue;
    let response = match request {
        ResidentRequestV1::Edge(request) => {
            let policy_store =
                policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
            crate::edge::evaluate_envelope_with_store_started(request, policy_store, started_at)
        }
        ResidentRequestV1::Operation(request) => match *request {
            ResidentOperationV1::CommandModel(request) => {
                crate::oneshot::evaluate_command_model_request(&request)
            }
            ResidentOperationV1::PreToolUse(request) => {
                crate::oneshot::evaluate_pre_tool_request(&request)
            }
            ResidentOperationV1::PolicySnapshotPush(request) => {
                let policy_store =
                    policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
                policy_store.push(&request)
            }
            ResidentOperationV1::ApprovalChallenge(request) => {
                let policy_store =
                    policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
                crate::approval::create_challenge(request, policy_store)
            }
            ResidentOperationV1::ApprovalValidate(request) => {
                let policy_store =
                    policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
                crate::approval::validate_approval(request, policy_store)
            }
            ResidentOperationV1::ApprovalConsume(request) => {
                let policy_store =
                    policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
                crate::approval::consume_approval(request, policy_store)
            }
            ResidentOperationV1::ApprovalChallengeV4(request) => {
                let policy_store =
                    policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
                crate::approval::approval_v4::create_challenge(request, policy_store)
            }
            ResidentOperationV1::ApprovalValidateV4(request) => {
                let policy_store =
                    policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
                crate::approval::approval_v4::validate_approval(request, policy_store)
            }
            ResidentOperationV1::ApprovalConsumeV4(request) => {
                let policy_store =
                    policy_store.ok_or_else(|| "native_policy_snapshot_unavailable".to_owned())?;
                crate::approval::approval_v4::consume_approval(request, policy_store)
            }
            ResidentOperationV1::Health(_request) => encode_response(&serde_json::json!({
                "status": "ready",
                "protocol_version": crate::RESIDENT_PROTOCOL_VERSION,
            })),
            ResidentOperationV1::Shutdown(_request) => {
                disposition = LifecycleDisposition::Shutdown;
                encode_response(&serde_json::json!({"status": "stopping"}))
            }
        },
        ResidentRequestV1::Hook(request) => {
            // Managed residents always carry a v3 policy store. The legacy
            // request has no generation-bound snapshot and must never reach a
            // semantic evaluator in that path.
            if policy_store.is_some() {
                Err("native_policy_snapshot_required".to_owned())
            } else {
                encode_response(&review_post_tool(&request))
            }
        }
    }?;
    Ok(ResidentEvaluation {
        response,
        disposition,
    })
}

pub(crate) fn strict_json_value(bytes: &[u8]) -> Result<Value, String> {
    crate::strict_json::parse(bytes)
}

pub(crate) fn encode_response<T: serde::Serialize>(value: &T) -> Result<Vec<u8>, String> {
    let encoded =
        serde_json::to_vec(value).map_err(|_| "native_response_encode_failed".to_owned())?;
    if encoded.len() > MAX_NATIVE_RESPONSE_BYTES {
        return Err("native_response_too_large".to_owned());
    }
    Ok(encoded)
}

pub(crate) fn error_response(code: &'static str, retryable: bool) -> Vec<u8> {
    serde_json::to_vec(&serde_json::json!({"error": code, "retryable": retryable})).unwrap_or_else(
        |_| b"{\"error\":\"native_response_encode_failed\",\"retryable\":false}".to_vec(),
    )
}

pub(crate) fn safe_error_response(code: &str, retryable: bool) -> Vec<u8> {
    if NATIVE_RESIDENT_LIFECYCLE_ERROR_CODES.contains(&code)
        || NATIVE_APPROVAL_ERROR_CODES.contains(&code)
        || guard_contracts::NATIVE_COMMAND_CONTROL_ERROR_CODES.contains(&code)
    {
        return serde_json::to_vec(&serde_json::json!({
            "error": code,
            "retryable": retryable,
        }))
        .unwrap_or_else(|_| error_response("native_response_encode_failed", false));
    }
    error_response("native_request_invalid_json", retryable)
}

#[cfg(test)]
mod tests {
    use super::{evaluate_resident_bytes, safe_error_response};
    use serde_json::Value;

    #[test]
    fn lifecycle_disposition_follows_strictly_validated_operation() {
        for (operation, disposition, status) in [
            ("health", super::LifecycleDisposition::Continue, "ready"),
            (
                "shutdown",
                super::LifecycleDisposition::Shutdown,
                "stopping",
            ),
        ] {
            let request = format!(r#"{{"operation":"{operation}","request":{{}}}}"#);
            let evaluated = evaluate_resident_bytes(request.as_bytes(), None).unwrap();
            assert_eq!(evaluated.disposition, disposition);
            let response: Value = serde_json::from_slice(&evaluated.response).unwrap();
            assert_eq!(response["status"], status);
        }
        for malformed in [
            br#"{"operation":"health","operation":"shutdown","request":{}}"#.as_slice(),
            br#"{"operation":"shutdown"}"#.as_slice(),
            br#"{"operation":"shutdown","request":{}} {}"#.as_slice(),
        ] {
            assert!(evaluate_resident_bytes(malformed, None).is_err());
        }
    }

    #[test]
    fn command_control_error_transport_preserves_only_registered_fixed_codes() {
        for code in guard_contracts::NATIVE_COMMAND_CONTROL_ERROR_CODES {
            for retryable in [false, true] {
                let response: Value =
                    serde_json::from_slice(&safe_error_response(code, retryable)).unwrap();
                assert_eq!(response["error"], *code);
                assert_eq!(response["retryable"], retryable);
                assert_eq!(response.as_object().unwrap().len(), 2);
            }
        }
        for untrusted in [
            "native_command_control_future_unregistered_code",
            "native_command_control_authority_missing:/private/guard-home",
            "native_command_control_authority_mac_invalid secret=fixture",
        ] {
            let response: Value =
                serde_json::from_slice(&safe_error_response(untrusted, false)).unwrap();
            assert_eq!(response["error"], "native_request_invalid_json");
        }
    }

    #[test]
    fn approval_error_transport_is_finite() {
        let known: Value =
            serde_json::from_slice(&safe_error_response("native_approval_replay", false))
                .expect("known approval error is JSON");
        assert_eq!(known["error"], "native_approval_replay");

        let unknown: Value = serde_json::from_slice(&safe_error_response(
            "native_approval_future_unregistered_code",
            false,
        ))
        .expect("redacted approval error is JSON");
        assert_eq!(unknown["error"], "native_request_invalid_json");

        let lifecycle: Value = serde_json::from_slice(&safe_error_response(
            "native_resident_start_in_progress",
            true,
        ))
        .expect("known lifecycle error is JSON");
        assert_eq!(lifecycle["error"], "native_resident_start_in_progress");

        let unknown_lifecycle: Value = serde_json::from_slice(&safe_error_response(
            "native_resident_future_unregistered_code",
            false,
        ))
        .expect("redacted lifecycle error is JSON");
        assert_eq!(unknown_lifecycle["error"], "native_request_invalid_json");

        let unknown_policy: Value = serde_json::from_slice(&safe_error_response(
            "native_policy_snapshot_future_unregistered_code",
            false,
        ))
        .expect("redacted policy error is JSON");
        assert_eq!(unknown_policy["error"], "native_request_invalid_json");
    }

    #[test]
    fn approval_requests_have_a_smaller_raw_payload_bound() {
        let padding = "x".repeat(super::NATIVE_APPROVAL_MAX_BYTES);
        let request =
            format!(r#"{{"operation":"approval_challenge","request":{{"padding":"{padding}"}}}}"#);
        assert_eq!(
            evaluate_resident_bytes(request.as_bytes(), None).unwrap_err(),
            "native_approval_request_bounds_exceeded"
        );
    }
}

use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::sync::mpsc::{sync_channel, Receiver, SyncSender, TrySendError};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

use sha2::{Digest, Sha256};
#[cfg(unix)]
use std::os::unix::net::UnixStream;

pub(crate) trait ResidentStream: Read + Write + Send {
    fn set_resident_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()>;
    fn set_resident_write_timeout(&self, timeout: Option<Duration>) -> io::Result<()>;
    fn set_resident_nonblocking(&self, nonblocking: bool) -> io::Result<()>;
    fn read_buffered_after_timeout_error(
        &mut self,
        _output: &mut [u8],
        _error: &io::Error,
        _deadline: Instant,
    ) -> Option<io::Result<usize>> {
        None
    }
    fn flush_after_timeout_error(
        &mut self,
        _error: &io::Error,
        _deadline: Instant,
    ) -> Option<io::Result<()>> {
        None
    }
    fn try_read_available(&mut self, output: &mut [u8]) -> io::Result<usize> {
        self.set_resident_nonblocking(true)?;
        let result = self.read(output);
        let restore = self.set_resident_nonblocking(false);
        match (result, restore) {
            (Err(error), Ok(())) if error.kind() == io::ErrorKind::WouldBlock => Ok(0),
            (result, Ok(())) => result,
            (_, Err(error)) => Err(error),
        }
    }
    fn configure_low_latency(&self) -> io::Result<()> {
        Ok(())
    }
}

impl ResidentStream for TcpStream {
    fn set_resident_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        TcpStream::set_read_timeout(self, timeout)
    }

    fn set_resident_write_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        TcpStream::set_write_timeout(self, timeout)
    }

    fn set_resident_nonblocking(&self, nonblocking: bool) -> io::Result<()> {
        self.set_nonblocking(nonblocking)
    }

    fn configure_low_latency(&self) -> io::Result<()> {
        self.set_nodelay(true)
    }
}

#[cfg(unix)]
impl ResidentStream for UnixStream {
    fn set_resident_read_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        UnixStream::set_read_timeout(self, timeout)
    }

    fn set_resident_write_timeout(&self, timeout: Option<Duration>) -> io::Result<()> {
        UnixStream::set_write_timeout(self, timeout)
    }

    fn set_resident_nonblocking(&self, nonblocking: bool) -> io::Result<()> {
        self.set_nonblocking(nonblocking)
    }

    #[cfg(target_os = "macos")]
    fn read_buffered_after_timeout_error(
        &mut self,
        output: &mut [u8],
        error: &io::Error,
        deadline: Instant,
    ) -> Option<io::Result<usize>> {
        use nix::sys::socket::{recv, MsgFlags};
        use std::os::fd::AsRawFd;

        closed_unix_peer_after_timeout_error(self, error)?;
        if Instant::now() >= deadline {
            return Some(Err(io::Error::from(io::ErrorKind::TimedOut)));
        }
        // Read only already available bytes or EOF. Do not change socket mode,
        // reuse an old blocking timeout, or wait for any further peer data.
        Some(recv(self.as_raw_fd(), output, MsgFlags::MSG_DONTWAIT).map_err(io::Error::from))
    }

    #[cfg(target_os = "macos")]
    fn flush_after_timeout_error(
        &mut self,
        error: &io::Error,
        deadline: Instant,
    ) -> Option<io::Result<()>> {
        closed_unix_peer_after_timeout_error(self, error)?;
        if Instant::now() >= deadline {
            return Some(Err(io::Error::from(io::ErrorKind::TimedOut)));
        }
        // UnixStream has no buffered writes: its actual flush is a no-op.
        // No request bytes are written again after the peer has closed.
        Some(Write::flush(self))
    }
}

#[cfg(target_os = "macos")]
fn closed_unix_peer_after_timeout_error(stream: &UnixStream, error: &io::Error) -> Option<()> {
    use nix::errno::Errno;
    use nix::poll::{poll, PollFd, PollFlags, PollTimeout};
    use std::os::fd::AsFd;

    // Darwin rejects socket timeout setters after a Unix peer closes, even
    // when its complete response remains buffered. EINVAL alone is insufficient:
    // independently require hangup on this same owned descriptor.
    if error.raw_os_error() != Some(Errno::EINVAL as i32) {
        return None;
    }
    let mut descriptors = [PollFd::new(stream.as_fd(), PollFlags::POLLIN)];
    if poll(&mut descriptors, PollTimeout::ZERO).ok()? != 1 {
        return None;
    }
    let events = descriptors[0].revents()?;
    if !events.contains(PollFlags::POLLHUP)
        || events.intersects(PollFlags::POLLERR | PollFlags::POLLNVAL)
    {
        return None;
    }
    Some(())
}

pub(crate) type BoxedResidentStream = Box<dyn ResidentStream>;

pub(crate) struct PendingRequest {
    pub(crate) stream: BoxedResidentStream,
    pub(crate) request_id: [u8; crate::FRAME_REQUEST_ID_BYTES],
    pub(crate) request_digest: [u8; crate::FRAME_DIGEST_BYTES],
    pub(crate) length: usize,
    pub(crate) payload_prefix: Vec<u8>,
    pub(crate) accepted_at: Instant,
}

pub(crate) fn constant_time_eq(left: &[u8], right: &[u8]) -> bool {
    if left.len() != right.len() {
        return false;
    }
    let mut difference = 0u8;
    for (left_byte, right_byte) in left.iter().zip(right) {
        difference |= left_byte ^ right_byte;
    }
    difference == 0
}

pub(crate) fn hmac_sha256(key: &[u8], label: &[u8], nonce: &[u8]) -> [u8; crate::AUTH_PROOF_BYTES] {
    const BLOCK_BYTES: usize = 64;
    let mut key_block = [0u8; BLOCK_BYTES];
    if key.len() > BLOCK_BYTES {
        let digest = Sha256::digest(key);
        key_block[..digest.len()].copy_from_slice(&digest);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    let mut inner_pad = [0x36u8; BLOCK_BYTES];
    let mut outer_pad = [0x5cu8; BLOCK_BYTES];
    for index in 0..BLOCK_BYTES {
        inner_pad[index] ^= key_block[index];
        outer_pad[index] ^= key_block[index];
    }

    let mut inner = Sha256::new();
    inner.update(inner_pad);
    inner.update(label);
    inner.update(nonce);
    let inner_digest = inner.finalize();

    let mut outer = Sha256::new();
    outer.update(outer_pad);
    outer.update(inner_digest);
    let digest = outer.finalize();
    let mut proof = [0u8; crate::AUTH_PROOF_BYTES];
    proof.copy_from_slice(&digest);
    proof
}

fn authenticate_resident_stream(
    stream: &mut dyn ResidentStream,
    token: &[u8; crate::AUTH_TOKEN_BYTES],
) -> Result<(), String> {
    stream
        .set_resident_read_timeout(Some(crate::AUTH_TIMEOUT))
        .map_err(|_| "native_resident_auth_timeout_failed".to_owned())?;
    stream
        .set_resident_write_timeout(Some(crate::AUTH_TIMEOUT))
        .map_err(|_| "native_resident_auth_timeout_failed".to_owned())?;
    let _ = stream.configure_low_latency();

    let mut nonce = [0u8; crate::AUTH_NONCE_BYTES];
    stream
        .read_exact(&mut nonce)
        .map_err(|_| "native_resident_auth_nonce_failed".to_owned())?;
    let server_proof = hmac_sha256(token, crate::SERVER_PROOF_LABEL, &nonce);
    stream
        .write_all(&server_proof)
        .map_err(|_| "native_resident_auth_proof_failed".to_owned())?;

    let mut client_proof = [0u8; crate::AUTH_PROOF_BYTES];
    stream
        .read_exact(&mut client_proof)
        .map_err(|_| "native_resident_auth_client_failed".to_owned())?;
    let expected = hmac_sha256(token, crate::CLIENT_PROOF_LABEL, &nonce);
    if !constant_time_eq(&client_proof, &expected) {
        return Err("native_resident_auth_rejected".into());
    }
    Ok(())
}

fn read_request_header(mut stream: BoxedResidentStream) -> Result<PendingRequest, String> {
    stream
        .set_resident_read_timeout(Some(crate::HEADER_TIMEOUT))
        .map_err(|_| "native_frame_timeout_failed".to_owned())?;
    let mut header = [0u8; crate::FRAME_HEADER_BYTES];
    stream
        .read_exact(&mut header)
        .map_err(|_| "native_frame_header_failed".to_owned())?;
    if !constant_time_eq(&header[..4], crate::REQUEST_MAGIC) {
        return Err("native_frame_version_mismatch".to_owned());
    }
    let mut request_id = [0u8; crate::FRAME_REQUEST_ID_BYTES];
    request_id.copy_from_slice(&header[4..4 + crate::FRAME_REQUEST_ID_BYTES]);
    let digest_start = 4 + crate::FRAME_REQUEST_ID_BYTES;
    let mut request_digest = [0u8; crate::FRAME_DIGEST_BYTES];
    request_digest.copy_from_slice(&header[digest_start..digest_start + crate::FRAME_DIGEST_BYTES]);
    let length = u32::from_be_bytes(
        header[crate::FRAME_HEADER_BYTES - 4..]
            .try_into()
            .map_err(|_| "native_frame_header_failed".to_owned())?,
    ) as usize;
    if length == 0 || length > crate::MAX_NATIVE_REQUEST_BYTES {
        return Err("native_request_too_large".to_owned());
    }
    Ok(PendingRequest {
        stream,
        request_id,
        request_digest,
        length,
        payload_prefix: Vec::new(),
        accepted_at: Instant::now(),
    })
}

fn write_bound_response(
    stream: &mut dyn ResidentStream,
    request_id: &[u8; crate::FRAME_REQUEST_ID_BYTES],
    response: &[u8],
) -> Result<(), String> {
    if response.is_empty() || response.len() > crate::MAX_NATIVE_RESPONSE_BYTES {
        return Err("native_response_too_large".to_owned());
    }
    stream
        .set_resident_write_timeout(Some(crate::RESPONSE_TIMEOUT))
        .map_err(|_| "native_frame_timeout_failed".to_owned())?;
    let digest = Sha256::digest(response);
    let mut header = Vec::with_capacity(crate::FRAME_HEADER_BYTES);
    header.extend_from_slice(crate::RESPONSE_MAGIC);
    header.extend_from_slice(request_id);
    header.extend_from_slice(&digest);
    header.extend_from_slice(&(response.len() as u32).to_be_bytes());
    stream
        .write_all(&header)
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    stream
        .write_all(response)
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    stream
        .flush()
        .map_err(|error| crate::hardening::write_error(&error, "native_frame_write_failed"))?;
    Ok(())
}

fn write_overload(pending: &mut PendingRequest) {
    let response = crate::resident_protocol::error_response("native_overloaded", true);
    let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
}

fn handle_pending_request(
    mut pending: PendingRequest,
    policy_store: Option<&crate::policy_store::PolicySnapshotStore>,
) {
    if crate::hardening::request_expired(pending.accepted_at) {
        let response =
            crate::resident_protocol::error_response("native_request_deadline_exceeded", true);
        let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
        return;
    }
    let _ = pending
        .stream
        .set_resident_read_timeout(Some(crate::PAYLOAD_TIMEOUT));
    let prefix_length = pending.payload_prefix.len();
    let mut request = vec![0u8; pending.length];
    request[..prefix_length].copy_from_slice(&pending.payload_prefix);
    let mut disposition = crate::resident_protocol::LifecycleDisposition::Continue;
    let response = if pending
        .stream
        .read_exact(&mut request[prefix_length..])
        .is_err()
    {
        crate::resident_protocol::error_response("native_frame_read_failed", false)
    } else {
        let digest = Sha256::digest(&request);
        if !constant_time_eq(&digest, &pending.request_digest) {
            crate::resident_protocol::error_response("native_request_digest_mismatch", false)
        } else {
            match catch_unwind(AssertUnwindSafe(|| {
                crate::observe_native_phase!(
                    ResidentEvaluate,
                    crate::resident_protocol::evaluate_resident_bytes_started(
                        &request,
                        policy_store,
                        pending.accepted_at,
                    )
                )
            })) {
                Ok(Ok(evaluation)) => {
                    disposition = evaluation.disposition;
                    evaluation.response
                }
                Ok(Err(reason)) => crate::resident_protocol::safe_error_response(&reason, false),
                Err(_panic) => {
                    crate::resident_protocol::error_response("native_runtime_panicked", false)
                }
            }
        }
    };
    if disposition == crate::resident_protocol::LifecycleDisposition::Shutdown {
        crate::managed_resident::request_shutdown();
    }
    let _ = write_bound_response(&mut *pending.stream, &pending.request_id, &response);
    if disposition == crate::resident_protocol::LifecycleDisposition::Shutdown {
        crate::managed_resident::shutdown_response_sent();
    }
}

fn spawn_workers<T, F>(count: usize, receiver: Receiver<T>, handler: F)
where
    T: Send + 'static,
    F: Fn(T) + Send + Sync + 'static,
{
    let receiver = Arc::new(Mutex::new(receiver));
    let handler = Arc::new(handler);
    for _ in 0..count {
        let receiver = Arc::clone(&receiver);
        let handler = Arc::clone(&handler);
        thread::spawn(move || loop {
            let next = match receiver.lock() {
                Ok(guard) => guard.recv(),
                Err(_) => return,
            };
            match next {
                Ok(item) => handler(item),
                Err(_) => return,
            }
        });
    }
}

pub(crate) fn start_resident_workers(
    token: Arc<[u8; crate::AUTH_TOKEN_BYTES]>,
    policy_store: Option<Arc<crate::policy_store::PolicySnapshotStore>>,
) -> SyncSender<BoxedResidentStream> {
    let (evaluation_sender, evaluation_receiver) =
        sync_channel::<PendingRequest>(crate::EVALUATION_QUEUE_CAPACITY);
    let evaluation_policy_store = policy_store.clone();
    spawn_workers(
        crate::EVALUATION_WORKERS,
        evaluation_receiver,
        move |pending| {
            handle_pending_request(pending, evaluation_policy_store.as_deref());
        },
    );

    let (authentication_sender, authentication_receiver) =
        sync_channel::<BoxedResidentStream>(crate::AUTH_QUEUE_CAPACITY);
    spawn_workers(
        crate::AUTH_WORKERS,
        authentication_receiver,
        move |mut stream| {
            if authenticate_resident_stream(&mut *stream, &token).is_err() {
                return;
            }
            let mut pending = match read_request_header(stream) {
                Ok(value) => value,
                Err(_) => return,
            };
            pending
                .payload_prefix
                .resize(pending.length.min(crate::AUTHENTICATED_PREFETCH_BYTES), 0);
            let available = match pending
                .stream
                .try_read_available(&mut pending.payload_prefix)
            {
                Ok(value) => value,
                Err(_) => return,
            };
            pending.payload_prefix.truncate(available);
            if available == pending.length {
                handle_pending_request(pending, policy_store.as_deref());
                return;
            }
            match evaluation_sender.try_send(pending) {
                Ok(()) => {}
                Err(TrySendError::Full(returned)) => {
                    let mut pending = returned;
                    write_overload(&mut pending);
                }
                Err(TrySendError::Disconnected(_returned)) => {}
            }
        },
    );
    authentication_sender
}

pub(crate) fn admit_connection(
    sender: &SyncSender<BoxedResidentStream>,
    stream: BoxedResidentStream,
) -> Result<(), String> {
    match sender.try_send(stream) {
        Ok(()) => Ok(()),
        Err(TrySendError::Full(_stream)) => Ok(()),
        Err(TrySendError::Disconnected(_stream)) => {
            Err("native_resident_worker_pool_stopped".to_owned())
        }
    }
}

